# Let's examine the input grid structure more carefully
import numpy as np
grid = [
    [0, 3, 3, 8, 3, 0],
    [0, 8, 3, 0, 3, 3],
    [3, 0, 3, 3, 3, 3],
    [3, 0, 3, 3, 3, 8],
    [9, 3, 0, 9, 8, 3],
    [0, 3, 0, 3, 8, 8],
    [3, 8, 0, 3, 3, 0],
    [9, 9, 8, 0, 8, 0]
]

# Look for diagonal patterns or lines
print("Grid analysis...")

# Count consecutive runs
for i, row in enumerate(grid):
    print(f"Row {i}: {row}")
    # Find max consecutive same values
    counts = {}
    current = row[0]
    count = 1
    for j in range(1, len(row)):
        if row[j] == current:
            count += 1
        else:
            if count > 2:
                print(f"  Long run at col {j-count}: value={current}, length={count}")
            current = row[j]
            count = 1
    if count > 2:
        print(f"  Long run at end: value={current}, length={count}")

# Also look at columns
for j in range(len(grid[0])):
    col = [grid[i][j] for i in range(len(grid))]
    print(f"\nCol {j}: {col}")
    counts = {}
    current = col[0]
    count = 1
    for i in range(1, len(col)):
        if col[i] == current:
            count += 1
        else:
            if count > 2:
                print(f"  Long run at row {i-count}: value={current}, length={count}")
            current = col[i]
            count = 1
    if count > 2:
        print(f"  Long run at end: value={current}, length={count}")

